using System;using System.IO;using System.Reflection;using System.Drawing;using System.Windows.Forms;using CircuitoStudio;
class DesktopLaunchTests{
 static GridItem Find(GridItem item){if(item.PropertyDescriptor!=null&&item.PropertyDescriptor.Name=="Name")return item;foreach(GridItem child in item.GridItems){var found=Find(child);if(found!=null)return found;}return null;}
 static int n;static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;static void Check(bool b,string name){n++;if(!b)throw new Exception(name);}static object Field(object s,string name){return s.GetType().GetField(name,flags).GetValue(s);}
 [STAThread]static int Main(){string dir=Path.Combine(Path.GetTempPath(),"debian-desktop-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);var field=typeof(Studio).GetField("userData",BindingFlags.Static|BindingFlags.NonPublic);object old=field.GetValue(null);string oldProjects=Environment.GetEnvironmentVariable("CIRCUITO_PROJECTS_DIR");string oldDesktop=Environment.GetEnvironmentVariable("CIRCUITO_DESKTOP");try{Environment.SetEnvironmentVariable("CIRCUITO_DESKTOP","debian");field.SetValue(null,Path.Combine(dir,"profile"));string file=Path.Combine(dir,"Projeto industrial Ω com espaços.circuito");var p=Project.CreateSample();p.Name="Projeto Debian Ω";p.Save(file);byte[] original=File.ReadAllBytes(file);using(var studio=new Studio()){studio.OpenProjectPath(file);Check(((Project)Field(studio,"project")).Name==p.Name,"file association loads exact Unicode project");Check((string)Field(studio,"currentFile")==Path.GetFullPath(file),"save targets opened file");Check(!(bool)Field(studio,"dirty"),"opening has no unsaved edits");object before=Field(studio,"project");bool refused=false;try{studio.OpenProjectPath(Path.Combine(dir,"missing.circuito"));}catch{refused=true;}Check(refused&&Object.ReferenceEquals(before,Field(studio,"project")),"invalid startup file keeps active project");Environment.SetEnvironmentVariable("CIRCUITO_PROJECTS_DIR",Path.Combine(dir,"Documentos","OpenEletric"));string folder=(string)typeof(Studio).GetMethod("Folder",flags).Invoke(studio,null);Check(folder==Environment.GetEnvironmentVariable("CIRCUITO_PROJECTS_DIR")&&Directory.Exists(folder),"save defaults to per-user document folder");studio.Show();Application.DoEvents();studio.Refresh();Check(studio.Visible,"real desktop window paints");var grid=(PropertyGrid)Field(studio,"properties");GridItem item=grid.SelectedGridItem;while(item.Parent!=null)item=item.Parent;item=Find(item);Check(item!=null,"flat Debian property editor exposes project name");var selected=(Project)Field(studio,"project");string oldName=selected.Name;item.PropertyDescriptor.SetValue(selected,"Editado no Debian Ω");typeof(PropertyGrid).GetMethod("OnPropertyValueChanged",flags).Invoke(grid,new object[]{new PropertyValueChangedEventArgs(item,oldName)});Check((bool)Field(studio,"dirty")&&selected.Name=="Editado no Debian Ω","edit through property event updates dirty state");string edited=Path.Combine(dir,"Editado.circuito");typeof(Studio).GetField("currentFile",flags).SetValue(studio,edited);Check((bool)typeof(Studio).GetMethod("Save",flags).Invoke(studio,new object[]{false})&&Project.Load(edited).Name==selected.Name,"flat editor changes save and reopen");studio.Refresh();Application.DoEvents();studio.Update();string output=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"debian-desktop.png");if(Environment.GetEnvironmentVariable("CIRCUITO_QA_VISUAL")=="1")using(var b=new Bitmap(studio.Width,studio.Height)){using(var g=Graphics.FromImage(b))g.CopyFromScreen(studio.Location,Point.Empty,studio.Size);b.Save(output);}studio.Hide();}Check(System.Linq.Enumerable.SequenceEqual(original,File.ReadAllBytes(file)),"opening and preview do not overwrite project");Console.WriteLine("PASS "+n+" Debian desktop assertions");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{field.SetValue(null,old);Environment.SetEnvironmentVariable("CIRCUITO_PROJECTS_DIR",oldProjects);Environment.SetEnvironmentVariable("CIRCUITO_DESKTOP",oldDesktop);Directory.Delete(dir,true);}}
}
